export interface SessionToken {
  accessToken: string;
  /** Millisecond epoch timestamp (per the injected clock) at which the token expires. */
  expiresAt: number;
}

export interface Clock {
  now(): number;
  setTimeout(fn: () => void, ms: number): unknown;
  clearTimeout(handle: unknown): void;
}

export interface SessionDeps {
  /**
   * Fetch a brand-new token (used on first access and after logout).
   * Must be provided.
   */
  fetchToken: () => Promise<SessionToken>;
  /**
   * Exchange the current token for a refreshed one. Optional; when absent,
   * refreshes fall back to fetchToken.
   */
  refreshToken?: (current: SessionToken) => Promise<SessionToken>;
  /** Injected time source. Defaults to real Date.now / timers. */
  clock?: Clock;
}

const REFRESH_WINDOW_MS = 30_000;

function defaultClock(): Clock {
  return {
    now: () => Date.now(),
    setTimeout: (fn, ms) => globalThis.setTimeout(fn, ms),
    clearTimeout: (handle) => globalThis.clearTimeout(handle as never),
  };
}

/**
 * Creates a session-token manager with proactive refresh:
 *
 * - `getToken()` returns the current token, transparently refreshing when it
 *   is within 30s of expiry (or already expired, or not yet fetched).
 * - Concurrent `getToken()` calls during a refresh share the single in-flight
 *   promise — `refreshToken`/`fetchToken` is invoked exactly once per flight.
 * - A failed refresh is retried once after 1s; if that also fails the error
 *   surfaces to callers, but no poisoned state is kept: the next `getToken()`
 *   starts clean and unblocks callers.
 * - `logout()` clears all state and cancels any scheduled refresh timer.
 */
export function createSession({ fetchToken, refreshToken, clock = defaultClock() }: SessionDeps) {
  let current: SessionToken | null = null;
  // Shared in-flight promise so concurrent getToken() calls coalesce.
  let inFlight: Promise<SessionToken> | null = null;
  let refreshTimer: unknown | null = null;

  function cancelScheduledRefresh(): void {
    if (refreshTimer !== null) {
      clock.clearTimeout(refreshTimer);
      refreshTimer = null;
    }
  }

  async function runFetch(fetch: () => Promise<SessionToken>): Promise<SessionToken> {
    const token = await fetch();
    current = token;
    scheduleProactiveRefresh(token);
    return token;
  }

  function scheduleProactiveRefresh(token: SessionToken): void {
    cancelScheduledRefresh();
    const delay = Math.max(0, token.expiresAt - REFRESH_WINDOW_MS - clock.now());
    refreshTimer = clock.setTimeout(() => {
      refreshTimer = null;
      // Fire and forget: failures surface to whoever calls getToken next.
      void ensureFresh().catch(() => {});
    }, delay);
  }

  /**
   * Returns a token that is guaranteed fresh (outside the expiry window).
   * Coalesces concurrent calls into one shared flight.
   */
  function ensureFresh(): Promise<SessionToken> {
    if (inFlight) return inFlight;

    const needsFetch =
      current === null ||
      clock.now() >= current.expiresAt - REFRESH_WINDOW_MS;

    if (!needsFetch) return Promise.resolve(current!);

    const doFetch = () =>
      current !== null && refreshToken
        ? refreshToken(current)
        : fetchToken();

    inFlight = runFetch(doFetch).finally(() => {
      inFlight = null;
    });
    return inFlight;
  }

  /**
   * Retry-once-after-1s wrapper around `ensureFresh`. On total failure the
   * error propagates but no stale/poisoned token state is retained, so the
   * next call starts a clean flight.
   */
  async function ensureFreshWithRetry(): Promise<SessionToken> {
    try {
      return await ensureFresh();
    } catch {
      cancelScheduledRefresh();
      await new Promise<void>((resolve) => clock.setTimeout(resolve, 1000));
      return await ensureFresh();
    }
  }

  return {
    /** Current token, refreshing proactively/transparently as needed. */
    getToken(): Promise<SessionToken> {
      return ensureFreshWithRetry();
    },

    /** Peek without side effects (null until first successful fetch). */
    peek(): SessionToken | null {
      return current;
    },

    /**
     * Clear all session state and cancel pending refresh scheduling.
     * The next getToken() performs a full fetchToken().
     */
    logout(): void {
      cancelScheduledRefresh();
      current = null;
      inFlight = null;
    },
  };
}

