import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { createSession, type SessionToken } from "../src/session.js";

/**
 * Deterministic clock driven by vitest fake timers.
 * now() reads vi.now(); setTimeout/clearTimeout delegate to vi's
 * timer queue so scheduled refreshes are fully scriptable.
 */
function makeFakeClock() {
  return {
    now: () => Date.now(),
    setTimeout: (fn: () => void, ms: number) => setTimeout(fn, ms),
    clearTimeout: (h: unknown) => clearTimeout(h as never),
  };
}

function token(accessToken: string, ttlFromNow: number): SessionToken {
  return { accessToken, expiresAt: Date.now() + ttlFromNow };
}

describe("createSession", () => {
  let fetchToken: ReturnType<typeof vi.fn>;
  let refreshToken: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    vi.useFakeTimers();
    fetchToken = vi.fn();
    refreshToken = vi.fn();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  /** Advance timers while letting pending promise callbacks run. */
  async function flush(ms = 0) {
    await vi.advanceTimersByTimeAsync(ms);
  }

  it("fetches a token on first getToken()", async () => {
    const t = token("a1", 60_000);
    fetchToken.mockResolvedValue(t);
    const s = createSession({ fetchToken, refreshToken, clock: makeFakeClock() });

    await expect(s.getToken()).resolves.toBe(t);
    expect(fetchToken).toHaveBeenCalledTimes(1);
    expect(refreshToken).not.toHaveBeenCalled();

    // Fresh token: subsequent calls do nothing.
    await expect(s.getToken()).resolves.toBe(t);
    expect(fetchToken).toHaveBeenCalledTimes(1);
    expect(refreshToken).toHaveBeenCalledTimes(0);
  });

  it("proactively refreshes when within 30s of expiry", async () => {
    const t1 = token("a1", 45_000); // enters the 30s window after 15s
    const t2 = token("a2", 120_000);
    fetchToken.mockResolvedValue(t1);
    refreshToken.mockResolvedValue(t2);
    const s = createSession({ fetchToken, refreshToken, clock: makeFakeClock() });

    await s.getToken();

    // Before the window: no refresh.
    await flush(14_999);
    expect(refreshToken).not.toHaveBeenCalled();

    // Cross the 29s-before-expiry mark: scheduled refresh fires.
    await flush(1);
    await vi.waitFor(() => expect(refreshToken).toHaveBeenCalledTimes(1));
    expect(refreshToken).toHaveBeenCalledWith(t1);

    // Callers transparently see the refreshed token.
    await expect(s.getToken()).resolves.toBe(t2);
    expect(fetchToken).toHaveBeenCalledTimes(1);
  });

  it("shares a single flight between concurrent getToken calls", async () => {
    let release!: (t: SessionToken) => void;
    const gate = new Promise<SessionToken>((r) => (release = r));
    const t1 = token("stale", 10_000); // already inside the window -> refresh immediately
    const t2 = token("fresh", 120_000);
    fetchToken.mockResolvedValue(t1);
    refreshToken.mockReturnValue(gate);
    const s = createSession({ fetchToken, refreshToken, clock: makeFakeClock() });

    await s.getToken(); // establish initial token

    const p1 = s.getToken();
    const p2 = s.getToken();
    const p3 = s.getToken();

    // All three are pending on the same shared flight.
    expect(refreshToken).toHaveBeenCalledTimes(1);

    release(t2);
    await Promise.all([p1, p2, p3]);

    // Exactly one underlying refresh despite three concurrent callers.
    expect(refreshToken).toHaveBeenCalledTimes(1);
    expect(await p1).toBe(t2);
    expect(await p2).toBe(t2);
    expect(await p3).toBe(t2);

    // And once resolved, later calls reuse the cached result.
    await s.getToken();
    expect(refreshToken).toHaveBeenCalledTimes(1);
  });

  it("retries once after 1s on refresh failure, then surfaces the error", async () => {
    const t1 = token("a1", 10_000); // inside window
    fetchToken.mockResolvedValue(t1);
    refreshToken
      .mockRejectedValueOnce(new Error("boom"))
      .mockResolvedValueOnce(token("a2", 120_000));
    const s = createSession({ fetchToken, refreshToken, clock: makeFakeClock() });

    await s.getToken();

    const pending = s.getToken();
    // Attach immediately so we can assert ordering without swallowing rejections.
    const settled = pending.then(
      (v) => ({ ok: true as const, v }),
      (e) => ({ ok: false as const, e }),
    );

    // First attempt fails...
    await flush(0);
    expect(refreshToken).toHaveBeenCalledTimes(1);
    // ...retry is scheduled ~1s later, not immediate.
    await flush(500);
    expect(refreshToken).toHaveBeenCalledTimes(1);
    await flush(500);
    expect(refreshToken).toHaveBeenCalledTimes(2);

    const result = await settled;
    expect(result.ok).toBe(true);
    if (result.ok) expect(result.v.accessToken).toBe("a2");
  });

  it("fails after retry also fails, keeps state clean so next call succeeds", async () => {
    const t1 = token("a1", 5_000); // inside window from the start of trouble
    fetchToken.mockResolvedValue(t1);
    refreshToken.mockRejectedValue(new Error("auth server down"));
    const consoleErr = vi.spyOn(console, "error").mockImplementation(() => {});
    const s = createSession({ fetchToken, refreshToken, clock: makeFakeClock() });

    await s.getToken();
    void consoleErr.mockRestore;

    await expect(s.getToken()).rejects.toThrow("auth server down");
    expect(refreshToken).toHaveBeenCalledTimes(2); // original + one retry

    // No poisoned state: next call starts a clean flight and can recover.
    refreshToken.mockResolvedValueOnce(token("a2", 120_000));
    await flush(0); // let any lingering timer work settle
    const t2 = { accessToken: "a2", expiresAt: Date.now() + 120_000 };
    refreshToken.mockResolvedValueOnce(t2);
    await expect(s.getToken()).resolves.toBe(t2);
    expect(refreshToken).toHaveBeenCalledTimes(4); // fail, retry-fail, succeed, succeed(retry of prior?) -- see below
  });

  it("logout cancels pending refresh scheduling and clears state", async () => {
    const t1 = token("a1", 45_000); // schedules a proactive refresh at +15s
    const t2 = token("anon", 60_000);
    fetchToken.mockResolvedValue(t1);
    refreshToken.mockResolvedValue(t2);
    const s = createSession({ fetchToken, refreshToken, clock: makeFakeClock() });

    await s.getToken();
    s.logout();

    // The scheduled refresh must never fire.
    await flush(60_000);
    expect(refreshToken).not.toHaveBeenCalled();

    // State is cleared: next getToken performs a full fetchToken().
    expect(s.peek()).toBeNull();
    fetchToken.mockClear();
    fetchToken.mockResolvedValue(t2);
    await expect(s.getToken()).resolves.toBe(t2);
    expect(fetchToken).toHaveBeenCalledTimes(1);
    expect(refreshToken).not.toHaveBeenCalled();
  });
});

